// Mock AI generator: stands in for prompt generation + Higgsfield image
// generation. It produces a caption, a prompt and a small PNG, with no
// external accounts. Replace this node with real generation steps.
const IMAGES = ["", "", "", ""];
const SUBJECTS = ['golden hour rooftop portrait', 'neon city night walk', 'cozy cafe morning', 'beach sunset, film grain', 'minimal studio portrait'];
const out = [];
for (const [i, item] of $input.all().entries()) {
  const req = item.json;
  const seed = Math.floor(Math.random() * 1e6);
  const subject = SUBJECTS[seed % SUBJECTS.length];
  const prompt = req.feedback
    ? `${req.previousPrompt || subject}. Revision request: ${req.feedback}`
    : `photorealistic AI avatar, ${subject}, 35mm, soft light`;
  const caption = req.feedback
    ? `Take two ✨ (${req.feedback})`
    : `New day, new vibe — ${subject} #aiavatar`;
  out.push({
    json: {
      request: { apiBaseUrl: req.apiBaseUrl, collection: req.collection, regeneratedFrom: req.regeneratedFrom || '' },
      item: {
        title: req.feedback ? `Regenerated: ${subject}` : `Avatar post: ${subject}`,
        content: caption,
        status: 'pending',
        source: 'n8n:instagram-avatar-demo',
        external_ref: `gen-${seed}`,
        metadata: {
          prompt, seed, model: 'mock-higgsfield-v1', caption,
          inspiration: 'mock-trend-scan', ...(req.regeneratedFrom ? { regenerated_from: req.regeneratedFrom, feedback: req.feedback } : {}),
        },
      },
    },
    binary: { data: { data: IMAGES[seed % IMAGES.length], mimeType: 'image/png', fileName: `avatar-${seed}.png` } },
    pairedItem: i,
  });
}
return out;

// Verifies the staq.ly signature and parses the event.
// Paste the webhook's secret below (Staqly → Webhooks). Leave empty to skip
// verification (local testing only). Verification needs the 'crypto' builtin:
// set NODE_FUNCTION_ALLOW_BUILTIN=crypto on n8n (the bundled compose does).
const CONFIG = {
  apiBaseUrl: 'http://api:3333',   // n8n on the host: http://localhost:3333
  webhookSecret: '',
  toleranceSeconds: 300,
};
const out = [];
for (const [i, item] of $input.all().entries()) {
  const raw = item.binary && item.binary.data
    ? await this.helpers.getBinaryDataBuffer(i, 'data')
    : Buffer.from(JSON.stringify(item.json.body));
  const h = item.json.headers || {};
  if (CONFIG.webhookSecret) {
    const crypto = require('crypto');
    const ts = h['x-staqly-timestamp'] || '';
    const expected = 'sha256=' + crypto.createHmac('sha256', CONFIG.webhookSecret).update(ts + '.').update(raw).digest('hex');
    const given = h['x-staqly-signature'] || '';
    const ok = given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
    if (!ok) throw new Error('Invalid Staqly signature');
    if (Math.abs(Date.now() / 1000 - Number(ts)) > CONFIG.toleranceSeconds) throw new Error('Stale Staqly webhook');
  }
  const event = JSON.parse(raw.toString('utf8'));
  // Deliveries are at-least-once: event.id / delivery_id can be used to dedupe.
  out.push({ json: { config: CONFIG, verified: !!CONFIG.webhookSecret, event, item: event.data.item || {} }, pairedItem: i });
}
return out;

// Mock Instagram publisher: pretends to post the approved image + caption.
// Replace with the real Instagram Graph API call in production.
return $input.all().map((item, i) => {
  const src = $('Verify & parse').itemMatching(i).json.item;
  const postId = '17' + String(Math.abs([...src.id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) | 0, 7))).padStart(14, '0');
  return {
    json: { instagram_post_id: postId, instagram_url: `https://instagram.example/p/${postId}`, caption: src.content,
            published_at: new Date().toISOString() },
    pairedItem: i,
  };
});

// Collects rejection feedback so future generations can learn from it.
return $input.all().map((item, i) => {
  const it = item.json.item;
  const log = Array.isArray(it.metadata?.feedback_log) ? it.metadata.feedback_log : [];
  return {
    json: { feedback_log: [...log, { feedback: it.feedback || item.json.event.data.feedback || '', at: item.json.event.created_at, by: item.json.event.actor?.name }] },
    pairedItem: i,
  };
});
